enum ClothingStyle: String, Codable, CaseIterable, Identifiable {
    case casual = "Casual"
    case formal = "Formal"
    case sporty = "Sporty"
    case vintage = "Vintage"
    case streetwear = "Streetwear"
    case bold = "Bold"
    case businessCasual = "Business Casual"
    case grunge = "Grunge"
    case comfy = "Comfy"
    
    var id: Self { self }
}

enum ClothingColor: String, Codable, CaseIterable, Identifiable {
    case white = "White"
    case black = "Black"
    case gray = "Gray"
    case blue = "Blue"
    case red = "Red"
    case orange = "Orange"
    case green = "Green"
    case yellow = "Yellow"
    case pink = "Pink"
    case purple = "Purple"
    case brown = "Brown"
    case multicolour = "Multicolour"
    
    var id: Self { self }
}
enum ClothingType: String, Codable, CaseIterable, Identifiable {
    // Upper Body
    case top = "Top"
    case outerwear = "Outerwear"
    
    // Lower Body
    case bottom = "Bottom"
    
    // Footwear
    case footwear = "Footwear"
    
    // Accessories & Extras
    case accessory = "Accessory"
    
    var id: Self { self }
}

@Model // @model classes can only support basic types, like string and int, but not enums. "String, Codable" have been applied to the enums so that they are read to the class as strings.
class ClothingItem {
//    var image: PhotosPickerItem
    var name: String
    var style: ClothingStyle
    var colour: ClothingColor
    var type: ClothingType
    @Attribute(.externalStorage) var image: Data? // @Attribute() tells SwiftData that the images should be stored right into the storage and not in the SQLite database. Keeps the app fast
//    var attire: ClothingAttire
    
    init(/*image: PhotosPickerItem, */name: String, style: ClothingStyle, colour: ClothingColor, type: ClothingType, image: Data?, parentOutfits: [Outfit]?/*, attire: ClothingAttire*/) {
//        self.image = image
        self.name = name
        self.style = style
        self.colour = colour
        self.type = type
        self.image = image
//        self.attire = attire
    }
    
    var description: String {
        "\(name) (\(style.rawValue), \(colour.rawValue))"
        }
}

@Model
class Outfit {
    var top: ClothingItem
    var bottom: ClothingItem
    var accessories: [ClothingItem] = []
    var footwear: ClothingItem
    var creationDayOfMonth: Int?
    var outfitRationale: String
    init(top: ClothingItem, bottom: ClothingItem, accessories: [ClothingItem], footwear: ClothingItem, creationDayOfMonth: Int?, outfitRationale: String) {
        self.accessories = accessories
        self.footwear = footwear
        self.top = top
        self.bottom = bottom
        self.creationDayOfMonth = creationDayOfMonth
        self.outfitRationale = outfitRationale
    }
    
    var AIdescription: String {
        return "Top:\(top.description) | Bottom:\(bottom.description) | Footwear:\(footwear.description)"
    }
    
    var description: String {
        return "Top: \(top.description)\nBottom: \(bottom.description)\nFootwear: \(footwear.description)\nCreated on \(creationDayOfMonth?.description ?? "unknown date")"
    }
}

@Model
class DailyOutfitList {
    var dailyOutfit: Outfit
    var eventOutfits: [Outfit]
    
    init(dailyOutfit: Outfit, eventOutfits: [Outfit]) {
        self.dailyOutfit = dailyOutfit
        self.eventOutfits = eventOutfits
    }
}

func colourDoesClash(colour1: ClothingColor, colour2: ClothingColor) -> Bool {
    if colour1 == colour2 {
        return false
    }
    
    switch colour1 {
    case .blue:
        switch colour2 {
        case .red, .orange, .black: return true
        default: return false
    }
    case .red:
        switch colour2 {
        case .blue, .orange, .purple, .green: return true
        default: return false
        }
    case .green:
        switch colour2 {
        case .orange, .red, .purple: return true
        default: return false
        }
    case .yellow:
        switch colour2 {
        case .pink, .purple: return true
        default: return false
        }
    case .orange:
        switch colour2 {
        case .blue, .pink, .red, .green, .purple: return true
        default: return false
        }
    case .purple:
        switch colour2 {
        case .red, .green, .yellow, .orange: return true
        default: return false
        }
    case .brown:
        switch colour2 {
        case .black: return true
        default: return false
        }
    case .black:
        switch colour2 {
        case .blue, .brown: return true
        default: return false
        }
    default:
        return false
    }
}

func styleDoesClash(style1: ClothingStyle, style2: ClothingStyle) -> Bool {
    if style1 == style2 {
        return false
    }
    
    switch style1 {
    case .casual:
        switch style2 {
        case .bold, .formal: return true
        default: return false
        }
    case .formal:
        switch style2 {
        case .casual, .sporty, .streetwear, .bold, .grunge, .comfy: return true
        default: return false
        }
    case .sporty:
        switch style2 {
        case .formal, .vintage: return true
        default: return false
        }
    case .vintage:
        switch style2 {
        case .sporty, .streetwear, .comfy: return true
        default: return false
        }
    case .streetwear:
        switch style2 {
        case .formal, .vintage, .businessCasual: return true
        default: return false
        }
    case .bold:
        switch style2 {
        case .casual, .formal, .businessCasual, .comfy: return true
        default: return false
        }
    case .businessCasual:
        switch style2 {
        case .streetwear, .bold, .grunge, .comfy: return true
        default: return false
        }
    case .grunge:
        switch style2 {
        case .formal, .businessCasual: return true
        default: return false
        }
    default:
        switch style2 {
        case .formal, .vintage, .bold, .businessCasual: return true
        default: return false
        }
    }
}

func separateClothingByType(clothingItems: [ClothingItem]) -> (tops: [ClothingItem], bottoms: [ClothingItem], footwear: [ClothingItem], misc: [ClothingItem]) {
    var tops: [ClothingItem] = []
    var bottoms: [ClothingItem] = []
    var footwear: [ClothingItem] = []
    var misc: [ClothingItem] = []
    
    for clothingItem in clothingItems {
        switch clothingItem.type {
            case .top:      tops.append(clothingItem)
            case .bottom:   bottoms.append(clothingItem)
            case .footwear: footwear.append(clothingItem)
            default:        misc.append(clothingItem)
        }
    }
    
    return (tops, bottoms, footwear, misc)
}

@Generable()
struct OutfitResponse {
    @Guide(description: "The index of the outfit you have chosen.", .range(0...7))
    let index: Int
    
    @Guide(description: "The reason WHY you chose this outfit. 1 sentence.")
    let rationale: String
}

func generateDailyOutfitAI(tops: [ClothingItem], bottoms: [ClothingItem], footwear: [ClothingItem], accessories: [ClothingItem], previousOutfits: [Outfit]) async -> Outfit {
    let model = SystemLanguageModel.default
    let session = LanguageModelSession()
    var randomOutfitCombinations: [Outfit] = []
    var randomOutfitCombinationDescriptions: [String] = []
    
    if model.isAvailable == true {
        
    for _ in 1...8 {
        var count = 25
        inner: while true {
            count -= 1

            let randomOutfit = Outfit(top: tops.randomElement()!, bottom: bottoms.randomElement()!, accessories: [], footwear: footwear.randomElement()!, creationDayOfMonth: Calendar.current.component(.day, from: Date()), outfitRationale: "")
            
            if count <= 0 {
                print("Unique outfit not found. defaulting to random possibly non-unique choice.")
                randomOutfitCombinations.append(randomOutfit)
                randomOutfitCombinationDescriptions.append(randomOutfit.AIdescription)
                break inner
            }
            
            for outfit in previousOutfits {
                if outfit.top == randomOutfit.top || outfit.bottom == randomOutfit.bottom || colourDoesClash(colour1: randomOutfit.top.colour, colour2: randomOutfit.bottom.colour) || styleDoesClash(style1: randomOutfit.top.style, style2: randomOutfit.bottom.style) {
                    continue inner
                }
            }
            
            randomOutfitCombinations.append(randomOutfit)
            randomOutfitCombinationDescriptions.append(randomOutfit.AIdescription)
            break inner
            }
        }
        
        let formattedOutfits = randomOutfitCombinationDescriptions.enumerated() // .enumerated adds the ability to show the index as well. $0.offset is the index and $0.element is the actual item
            .map { "[\($0.offset)] \($0.element)" }
            .joined(separator: "\n")
        
        do {
            print(randomOutfitCombinations.count)
            let prompt = """
                You are a professional fashion design AI. Your task is to analyze a list of outfits and select the single best option.

                CRITERIA FOR "FASHIONABLE":
                - Color Harmony: Look for complementary colors or intentional tonal palettes.
                - Style Cohesion: High marks for pieces that share a cohesive aesthetic (e.g., Minimalist + Minimalist, Retro + Bohemian). Avoid jarring style clashes (e.g., Avant Garde + Sporty).
            
            \(formattedOutfits) 
            """

            print(prompt)
            
            let response = try await session.respond(to: prompt, generating: OutfitResponse.self)
            
            print("AI PICKED INDEX: \(response.content.index)")
            if randomOutfitCombinations.indices.contains(response.content.index) {
                randomOutfitCombinations[response.content.index].outfitRationale = response.content.rationale
                return randomOutfitCombinations[response.content.index]
            } else {
                print("AI HALLUCINATED THE INDEX BOI")
                return generateDailyOutfit(tops: tops, bottoms: bottoms, footwear: footwear, accessories: accessories, previousOutfits: previousOutfits)
            }
        } catch {
            print("failed : \(error)")
            return generateDailyOutfit(tops: tops, bottoms: bottoms, footwear: footwear, accessories: accessories, previousOutfits: previousOutfits)
        }
    }
    print("Model is not avaliable \(model.availability)")
    return generateDailyOutfit(tops: tops, bottoms: bottoms, footwear: footwear, accessories: accessories, previousOutfits: previousOutfits)
}

func generateDailyOutfit(tops: [ClothingItem], bottoms: [ClothingItem], footwear: [ClothingItem], accessories: [ClothingItem], previousOutfits: [Outfit]) -> Outfit {
    var count = 50
    while true {
        let randomTop = tops.randomElement()!
        let randomBottom = bottoms.randomElement()!
        let randomFootwear = footwear.randomElement()!
        
        if count <= 1 {
            return Outfit(top: randomTop, bottom: randomBottom, accessories: [], footwear: randomFootwear, creationDayOfMonth: Calendar.current.component(.day, from: Date()), outfitRationale: "")
        }
        
        if colourDoesClash(colour1: randomTop.colour, colour2: randomBottom.colour) || styleDoesClash(style1: randomTop.style, style2: randomBottom.style) {
            count -= 1
            continue;
        } else {
            return Outfit(top: randomTop, bottom: randomBottom, accessories: [], footwear: randomFootwear, creationDayOfMonth: Calendar.current.component(.day, from: Date()), outfitRationale: "")
        }
    }
}
